from module_adapters._graph_extended_support import Diagram,validate
SOURCE='ban-modules/attention.py';BC='ban-modules/bc.py';FC='ban-modules/fc.py';KEY='bilinear_attention'
LINKS=[('v','vproject.drop','in','tensor'),('q','qproject.drop','in','tensor'),('scoreparams','score','h_mat','parameter_operand'),('scoreparams','score','h_bias','parameter_operand'),('vproject.extra','score','V','tensor'),('qproject.relu','score','Q','tensor'),('score','mask','logits','tensor'),('v','mask','mask_input','retained_value'),('mask','normalize.flat','in','tensor'),('v','normalize.flat','v_num','shape_dependency'),('q','normalize.flat','q_num','shape_dependency'),('v','normalize.view','v_num','shape_dependency'),('q','normalize.view','q_num','shape_dependency'),('normalize.view','output','probabilities','tensor'),('mask','output','masked_logits','retained_value')]
REQUIRED={'score':dict(expression="torch.einsum('xhyk,bvk,bqk->bhvq', (self.h_mat, v_, q_)) + self.h_bias",glimpse=2,k=3,h_mat_weight_normalized=True),'normalize.softmax':dict(dim=2,normalization_axis='joint V*Q per glimpse'),'mask':dict(mask_from='v.abs().sum(2)==0',masked_fill='-inf',mutation='logits.data.masked_fill_'),'vproject.extra':dict(p=.5),'qproject.drop':dict(p=.2)}
CONTRACTS=[('BiAttention.forward_all','nn.functional.softmax(logits.view(-1, self.glimpse, v_num * q_num), 2)'),('BiAttention.forward_all','v.abs().sum(2)'),('BiAttention.forward_all','logits.data.masked_fill_(mask.data, mask_with)'),('BiAttention.forward_all','v.size(1)'),('BiAttention.forward_all','q.size(1)'),('BiAttention.forward_all','p.view(-1, self.glimpse, v_num, q_num)')]
EXTRA_CONTRACTS={BC:[('BCNet.forward',"torch.einsum('xhyk,bvk,bqk->bhvq', (self.h_mat, v_, q_)) + self.h_bias")],FC:[('FCNet.__init__','weight_norm(nn.Linear(dims[-2], dims[-1]), dim=None)')]}
def projections(d,rank,extra=False):
 init=d.ref('BCNet.__init__',BC);bcforward=d.ref('BCNet.forward' if extra else 'BCNet.forward_with_weights',BC);fcinit=d.ref('FCNet.__init__',FC);fcforward=d.ref('FCNet.forward',FC)
 for suffix,dim in [('v',8),('q',6)]:
  steps=[('drop','Dropout .2','dropout',f'[B,{5 if suffix=="v" else 3},{dim}]',dict(p=.2,source=[fcinit,fcforward])),('linear',f'WeightNorm Linear {dim} -> 12','linear',f'[B,{5 if suffix=="v" else 3},12]',dict(parameter_scope=suffix+'_net.main.1',weight_normalization_dim=None,opaque_weight_norm=True,bias=True,source=fcinit)),('relu','ReLU','relu',f'[B,{5 if suffix=="v" else 3},12]',dict(source=[fcinit,fcforward]))]
  if extra and suffix=='v':steps.append(('extra','Extra attention Dropout .5','dropout','[B,5,12]',dict(p=.5,source=[init,bcforward])))
  d.stage(suffix+'project',suffix.upper()+' projection',f'[B,{5 if suffix=="v" else 3},12]',rank,steps,source=[bcforward,fcforward])
def build():
 d=Diagram(KEY,'BAN bilinear attention',SOURCE,'BiAttention.forward_all','BiAttention.forward_all(v,q,v_mask=True,logit=False); low-rank BCNet h_out2<=32 branch; excludes VQA classifier/counter.',dict(x_dim=8,y_dim=6,z_dim=4,k=3,glimpse=2,V=5,Q=3,v_mask=True,logit=False,output_tuple=['probabilities','masked_logits'],norm='joint V*Q per glimpse',mode='caller train/eval',between_examples_weight_sharing='not implied'))
 init=d.ref('BiAttention.__init__');d.input('v','Visual features V','[B,5,8]');d.input('q','Language features Q','[B,3,6]');d.input('scoreparams','Owned h_mat(g,v), h_bias','h[1,2,1,12]; b[1,2,1,1]',kind='parameter',source=[init,d.ref('BCNet.__init__',BC)],h_mat_weight_normalized=True,parameter_families=['logits.h_mat_g','logits.h_mat_v','logits.h_bias']);projections(d,0,True)
 d.node('score','Low-rank bilinear scores + bias','einsum','[B,2,5,3]',1,source=d.ref('BCNet.forward',BC),**REQUIRED['score'],parameter_scope='logits.h_mat_{g,v} and logits.h_bias')
 d.node('mask','Mask zero visual rows / -inf','control','[B,2,5,3]',2,**REQUIRED['mask'])
 d.stage('normalize','Normalize all V,Q pairs','[B,2,5,3]',3,[('flat','View V*Q positions','tensor','[B,2,15]',dict()),('softmax','Softmax dim=2','softmax','[B,2,15]',REQUIRED['normalize.softmax']),('view','Restore V,Q axes','tensor','[B,2,5,3]',dict())])
 for s,t,p,r in sorted(LINKS,key=lambda e:e[0]=='scoreparams'):
  side='right' if s=='scoreparams' or r=='shape_dependency' and s=='q' else 'left'
  d.edge(s,t,p,r,ss=side if s=='scoreparams' or r in ('shape_dependency','retained_value') else 'out',ds=side if s=='scoreparams' or r in ('shape_dependency','retained_value') else 'in',sp=p if s=='scoreparams' else 'shape' if r=='shape_dependency' else 'out')
 return d.build(d.entry,'p, logits: 2 x [B,2,5,3]','BilinearAttention.md',['h_out2<=32 selects the real low-rank einsum branch with k3 factors. h_mat is weight_norm reparameterized by BiAttention; it is not a plain final Parameter named h_mat.','FCNet includes Dropout.2 before WeightNorm Linear and ReLU; only the visual path gets the extra attention Dropout.5.','Zero visual rows are detected from original v; source mutates logits.data with -inf, then Softmax normalizes flattened V*Q jointly for each glimpse.','forward_all returns p and masked logits; logit=True alternate raw-only path is outside this selected profile.'],['Do not substitute Transformer QK^T/sqrt(d): BAN uses a learned three-operand low-rank bilinear einsum.','Do not normalize only over question tokens or mask zero question rows.','Do not silently replace the source data mutation with a different autograd implementation.'])
SOURCE_PORTS=[('scoreparams','score','h_mat','h_mat'),('scoreparams','score','h_bias','h_bias'),('v','normalize.flat','v_num','shape'),('q','normalize.flat','q_num','shape'),('v','normalize.view','v_num','shape'),('q','normalize.view','q_num','shape')]
def validate_ir(ir):return validate(ir,KEY,REQUIRED,LINKS,dict(output_tuple=['probabilities','masked_logits'],v_mask=True,logit=False),SOURCE_PORTS)
